-- Migration 005 — sku_labels (Production Planner, spec B8.9 barcodes/labels)
-- Focused extract from SKU_CHILD (960 rows × 137 cols). Only the fields the barcode/label
-- generator needs: the THREE EAN-13 numbers (product/carton/inner), label name strings,
-- carton qty, swatch art URL, GRS material text, plus identity (size/category).
-- Everything else in SKU_CHILD (pricing MERGE strings, sizes, availability, target cover)
-- overlaps the existing planner.products/demand tables and is intentionally NOT copied here.
-- HOW TO APPLY: tested on sandbox; BEN runs on live.

create table if not exists planner.sku_labels (
  sku                text primary key,
  status             text,
  size               text,
  category           text,
  subcategory        text,
  main_supplier      text,
  carton_qty         int,
  product_barcode    text,   -- sku_barcode (EAN-13) -> product label
  carton_barcode     text,   -- carton_barcode (EAN-13) -> carton label
  inner_barcode      text,   -- inner_barcode (EAN-13) -> carton label (inner)
  barcode_sku_name   text,   -- barcode_sku_name_final
  barcode_carton_name text,  -- e.g. "BOX OF 50 x ACTIVE-SML-ORANGE"
  barcode_inner_name text,
  swatch_url         text,   -- colour_swatch_url (composited into product label)
  grs_material       text,   -- GRS_material_carton
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);

comment on table planner.sku_labels is 'Barcode/label source per SKU (extract of SKU_CHILD) — spec B8.9.';

